import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import {
  HouseDoorFill,
  ListCheck,
  Calendar3,
  BarChart,
  People,
  Gear,
  QuestionCircle,
  BoxArrowRight,
  List,
  Clipboard,
  PersonLinesFill,
  Kanban,
  Check2Square,
  Person,
  Question,
  QuestionCircleFill,
  Line,
  HddRack
} from "react-bootstrap-icons";
import {
  Archive, CheckSquare, ClipboardList, Cpu, Database,
  Factory, GitBranch, LayoutDashboard, ListTodo, MapPin,
  ShieldCheck, WashingMachine, Workflow
} from "lucide-react";
import "bootstrap/dist/css/bootstrap.min.css";
import "../css/SideBar.css"
import { usePermissionStore } from "../auth/Permission";
import { FaBookOpen, FaPlusCircle } from "react-icons/fa";
import { FaCogs } from "react-icons/fa"
import { FaProjectDiagram } from "react-icons/fa";
import { RiDashboard2Fill } from "react-icons/ri";
const Sidebar = ({ moduleName }) => {
  // const [moduleName, setModuleName] = useState(moduleName);
  const [isCollapsed, setIsCollapsed] = useState(false);
  // const hasPermission = usePermissionStore((state) => state.hasPermission);
  const permissions = usePermissionStore((state) => state.permissions);
  // simple permission checker
  const hasPermission = (permissionName) => permissions.includes(permissionName);

  // Auto-collapse if screen < 1000px
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 1500) {
        setIsCollapsed(true);
      } else {
        setIsCollapsed(false);
      }
    };
    window.addEventListener("resize", handleResize);
    handleResize(); // run on load
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return (
    <div
      className={`d-flex flex-column text-white transition-all`}
      style={{
        width: isCollapsed ? "50px" : "260px",
        height: "100vh",
        position: "sticky",
        top: 0,
        backgroundColor: "#0f6b5b"
      }}
    >
      {/* Toggle Button */}
      <button
        className="btn btn-sm btn-outline-light m-2 p-0"
        onClick={() => setIsCollapsed(!isCollapsed)}
      >
        <List size={28} />
      </button>

      {/* Logo */}
      {!isCollapsed && (
        <a
          href="/WebApplication/dashboard"
          className="d-flex align-items-center mb-3 mb-md-0 me-md-auto text-white text-decoration-none px-3"
        >
          <span className="fs-5 fw-bold">
            <Database size={20} className="me-2" />
            {moduleName && (
              moduleName
            )}</span>
        </a>
      )}
      <hr className="border-light mx-2" />

      {/* MENU */}
      <ul className="nav nav-pills flex-column mb-auto">

        {hasPermission("plantMaster") && (
          <li className="nav-item">
            <Link to="plantMaster" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <Factory size={20} className="me-2" />
              {!isCollapsed && "Plant Master"}
            </Link>
          </li>
        )}

        {hasPermission("locationMaster") && (
          <li className="nav-item">
            <Link to="locationMaster" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <MapPin size={20} className="me-2" />
              {!isCollapsed && "Loctaion Master"}
            </Link>
          </li>
        )}

        {hasPermission("rackMaster") && (
          <li className="nav-item">
            <Link to="rackMaster" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <Archive size={20} className="me-2" />
              {!isCollapsed && "Rack Master"}
            </Link>
          </li>
        )}

        {hasPermission("roleMaster") && (
          <li className="nav-item">
            <Link to="roleMaster" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <Cpu size={20} className="me-2" />
              {!isCollapsed && "Role Master"}
            </Link>
          </li>
        )}

        {hasPermission("processMaster") && (
          <li className="nav-item">
            <Link to="processMaster" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <Workflow size={20} className="me-2" />
              {!isCollapsed && "Process Master"}
            </Link>
          </li>
        )}

        {hasPermission("devicesMaster") && (
          <li className="nav-item">
            <Link to="devicesMaster" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <GitBranch size={20} className="me-2" />
              {!isCollapsed && "Devices Master"}
            </Link>
          </li>
        )}

        {/* {hasPermission("Customers") && (
          <li className="nav-item">
            <Link to="customers" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <People size={20} className="me-2" />
              {!isCollapsed && "Customers"}
            </Link>
          </li>
        )}

        {hasPermission("Contact Person") && (
          <li className="nav-item">
            <Link to="contactPerson" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <PersonLinesFill size={20} className="me-2" />
              {!isCollapsed && "Contact Person"}
            </Link>
          </li>
        )}

        {hasPermission("Users") && (
          <li className="nav-item">
            <Link to="users" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <Person size={20} className="me-2" />
              {!isCollapsed && "Users"}
            </Link>
          </li>
        )}

        {hasPermission("Projects") && (
          <li>
            <Link to="projects" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <Clipboard size={20} className="me-2" />
              {!isCollapsed && "Projects"}
            </Link>
          </li>
        )}

        {hasPermission("Projects & Tasks") && (
          <li>
            <Link to="tasks" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <Check2Square size={20} className="me-2" />
              {!isCollapsed && "Projects & Tasks"}
            </Link>
          </li>
        )}

        {hasPermission("Groups & Tasks") && (
          <li>
            <Link to="groups" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <ClipboardList size={20} className="me-2" />
              {!isCollapsed && "Groups & Tasks"}
            </Link>
          </li>
        )}

        {hasPermission("Roles & Authority") && (
          <li>
            <Link to="roles" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
              <ShieldCheck size={20} className="me-2" />
              {!isCollapsed && "Roles & Authority"}
            </Link>
          </li>
        )} */}
      </ul>

      <hr className="border-light mx-2" />
      {/* GENERAL */}
      <ul className="nav nav-pills flex-column mb-auto">
        <li>
          <Link to="logout" className="nav-link text-white d-flex align-items-center px-3 sidebar-link">
            <BoxArrowRight size={20} className="me-2" />
            {!isCollapsed && "Logout"}
          </Link>
        </li>
      </ul>
    </div>
  );
};

export default Sidebar;
