import React, { useState } from "react";
import { Card, Button, ProgressBar, Table, Form } from "react-bootstrap";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min.js";
import { ArrowDown, BookOpenIcon, Download } from "lucide-react";

const StaticBackDropModal = ({ alert, setDismissAlertNull }) => {

    const openFileInNewTab = async (resource) => {
        try {

            const fileUrl = `${resource.resourcePath}${resource.resourceName}${resource.resourceExtension}`;
            const response = await fetch(fileUrl);

            if (!response.ok) {
                throw new Error("File not found or network error");
            }

            const blob = await response.blob();
            const contentType = response.headers.get("content-type");

            // Create blob URL
            const fileBlobUrl = URL.createObjectURL(new Blob([blob], { type: contentType }));

            // Open in new tab
            window.open(fileBlobUrl, "_blank");

            // Optional: revoke later after opening
            setTimeout(() => URL.revokeObjectURL(fileBlobUrl), 10000);
        } catch (error) {
            console.error("Failed to open file:", error);
        }
    };


    const downloadFile = async (resource) => {
        try {
            const fileUrl = `${resource.resourcePath}${resource.resourceName}${resource.resourceExtension}`;

            const response = await fetch(fileUrl, {
                method: "GET"
            });

            if (!response.ok) {
                throw new Error("File not found or network error");
            }

            const contentType = response.headers.get("content-type");
            console.log("Content-Type:", contentType);

            if (contentType && contentType.includes("text/html")) {
                // alert("❌ Server returned HTML instead of file. Check file path or permissions.");
                console.log("Server returned HTML instead of file. Check file path or permissions. ");
                return;
            }

            const blob = await response.blob();

            const url = URL.createObjectURL(blob);
            const link = document.createElement("a");

            link.href = url;
            link.download = resource.resourceName;
            document.body.appendChild(link);
            link.click();

            link.remove();
            URL.revokeObjectURL(url);
        } catch (error) {
            console.error("Download failed:", error);
        }
    };

    const [fromDate, setFromDate] = useState("");
    const [toDate, setToDate] = useState("");
    const [reports, setReports] = useState({
        stationScore: true,
        trainingHours: false,
        passFail: false,
        monthlyTrend: false,
        lowPerformers: false,
    });


    const handleCheckboxChange = (e) => {
        const { name, checked } = e.target;
        setReports(prev => ({
            ...prev,
            [name]: checked
        }));
    };




    if (!alert) return null;
    return (
        <>
            <div
                className="modal fade show d-block"
                tabIndex="-1"
                role="dialog"
                style={{ backgroundColor: "rgba(0,0,0,0.5)" }}
            >
                <div className="modal-dialog modal-lg modal-dialog-centered">
                    <div className="modal-content">

                        {/* Header */}
                        <div className="modal-header bg-light">
                            <h5 className="modal-title">
                                📊 Download Performance Report
                            </h5>
                            <button
                                type="button"
                                className="btn-close"
                                onClick={setDismissAlertNull}
                            ></button>
                        </div>

                        {/* Body */}
                        <div className="modal-body">

                            {/* Date Filters */}
                            <div className="row mb-4">
                                <div className="col-md-6">
                                    <label className="form-label fw-bold">From Date</label>
                                    <input
                                        type="date"
                                        className="form-control"
                                        value={fromDate}
                                        onChange={(e) => setFromDate(e.target.value)}
                                    />
                                </div>

                                <div className="col-md-6">
                                    <label className="form-label fw-bold">To Date</label>
                                    <input
                                        type="date"
                                        className="form-control"
                                        value={toDate}
                                        onChange={(e) => setToDate(e.target.value)}
                                    />
                                </div>
                            </div>

                            {/* Report Selection */}
                            <div className="border rounded p-3 bg-light">
                                <h6 className="mb-3 fw-bold">
                                    Select Report Sections (Excel Sheets)
                                </h6>

                                <div className="row">
                                    <div className="col-md-6">
                                        <div className="form-check">
                                            <input
                                                className="form-check-input"
                                                type="checkbox"
                                                name="stationScore"
                                                checked={reports.stationScore}
                                                onChange={handleCheckboxChange}
                                            />
                                            <label className="form-check-label">
                                                Station-wise Score
                                            </label>
                                        </div>

                                        <div className="form-check">
                                            <input
                                                className="form-check-input"
                                                type="checkbox"
                                                name="trainingHours"
                                                checked={reports.trainingHours}
                                                onChange={handleCheckboxChange}
                                            />
                                            <label className="form-check-label">
                                                Training Hours
                                            </label>
                                        </div>

                                        <div className="form-check">
                                            <input
                                                className="form-check-input"
                                                type="checkbox"
                                                name="passFail"
                                                checked={reports.passFail}
                                                onChange={handleCheckboxChange}
                                            />
                                            <label className="form-check-label">
                                                Pass / Fail Summary
                                            </label>
                                        </div>
                                    </div>

                                    <div className="col-md-6">
                                        <div className="form-check">
                                            <input
                                                className="form-check-input"
                                                type="checkbox"
                                                name="monthlyTrend"
                                                checked={reports.monthlyTrend}
                                                onChange={handleCheckboxChange}
                                            />
                                            <label className="form-check-label">
                                                Monthly Trend
                                            </label>
                                        </div>

                                        <div className="form-check">
                                            <input
                                                className="form-check-input"
                                                type="checkbox"
                                                name="lowPerformers"
                                                checked={reports.lowPerformers}
                                                onChange={handleCheckboxChange}
                                            />
                                            <label className="form-check-label">
                                                Low Performers
                                            </label>
                                        </div>
                                    </div>
                                </div>
                            </div>

                        </div>

                        {/* Footer */}
                        <div className="modal-footer">
                            <button
                                type="button"
                                className="btn btn-secondary"
                                onClick={setDismissAlertNull}
                            >
                                Cancel
                            </button>

                            <button
                                type="button"
                                className="btn btn-success px-4"
                            // onClick={handleDownloadReport}
                            >
                                <Download className="me-1" />
                                <span className="d-lg-inline me-1">Download Excel</span>
                            </button>
                        </div>

                    </div>
                </div>
            </div>
        </>
    );
}

export default StaticBackDropModal;
