import React, { useState, useEffect } from "react";
import InputField from "../components/InputFields";
import myLogo from "../images/default2.png";
import { Link } from "react-router-dom";
import axios from "axios";
import { ArrowLeft, PlusCircle } from "react-bootstrap-icons";
import { useLocation, useNavigate } from "react-router-dom";
import { useOutletContext } from "react-router-dom";
import SearchInputFields from "../components/SearchInputFields"
import Pager from "../components/Pager";
import { Table, Button, Modal, Form } from "react-bootstrap";
import {
    HouseDoorFill,
    ListCheck,
    Calendar3,
    BarChart,
    People,
    Gear,
    QuestionCircle,
    BoxArrowRight,
    PersonCircle,
    Search,
    X
} from "react-bootstrap-icons";
import { masterName } from "framer-motion/client";
import LoadingSpinner from "../components/LoadingSpinner";
import { ClipboardList } from "lucide-react";
const BASE_URL = process.env.REACT_APP_BASE_URL;

const NewLocationForm = () => {
    const [loading, setLoading] = useState(true);
    const [plantId, setPlantId] = useState("");
    const [plantName, setPlantName] = useState("");
    const [plantCode, setPlantCode] = useState("");
    const [plantDescription, setPlantDescription] = useState("");
    const [plantCity, setPlantCity] = useState("");
    const [plantState, setPlantState] = useState("");
    const [plantPincode, setPlantPincode] = useState("");
    const [plantAddress, setPlantAddress] = useState("")
    const [status, setStatus] = useState("");
    const [statusTypes, setStatusTypes] = useState(["Enable", "Disable"]);
    const [error, setError] = useState("");
    const { setAlert } = useOutletContext();
    const location = useLocation();
    const { object } = location.state || {};
    const [selectedImage, setSelectedImage] = useState(null); // real File
    const [previewUrl, setPreviewUrl] = useState(null);
    const [image, setImage] = useState(null);       // preview

    const handleImageChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setSelectedImage(file); // 👈 real File object
            setPreviewUrl(URL.createObjectURL(file)); // 👈 preview blob URL
        } else {
            alert("Please Select a JPG and PNG image.");
        }
    };

    useEffect(() => {
        // // Runs on mount
        // loadCustomerListData();
        // loadUserListData();
        // loadPersonListData();
        // loadGroupListData();

        // Runs when object changes
        if (object) {
            setPlantId(object.plantId || "");
            setPlantName(object.plantName || "");
            setPlantCode(object.plantCode || "");
            setPlantAddress(object.plantAddress || "");
            setPlantDescription(object.plantDescription || "");
            // (object.personName || "");
            // setProjectManager(object.projectManager || "");
            // setStartDate(object.startDate || "");
            // setEndDate(object.endDate || "");
            // setStatus(object.status || "");
            // setNote(object.note || "");
            // setGroupName(object.groupName || "");
            setImage(object.image || "")
            setPreviewUrl(object.image || "");
        }

        setLoading(false);
    }, [object]);

    const resetForm = async (e) => {
        setPlantId("");
        setPlantName("");
        setPlantCode("");
        setPlantAddress("");
        // setPersonName("");
        // setProjectManager("");
        // setEndDate("");
        // setStartDate("");
        // setStatus("");
        // setNote("");
        // setGroupName("");
        setPreviewUrl("");
        setImage("");
    }

    // // Handle form change
    // const loadCustomerListData = async () => {
    //     const response = await axios.get(
    //         BASE_URL + "/WebApplication/Controllers/getAllCustomerInList",
    //         { withCredentials: true, } // 🚨 This ensures browser stores cookie 
    //     );
    //     setCustomerTypes(response.data);
    // };

    // // Handle form change
    // const loadPersonListData = async () => {
    //     const response = await axios.get(
    //         BASE_URL + "/WebApplication/Controllers/getAllContactPersonInList",
    //         { withCredentials: true, } // 🚨 This ensures browser stores cookie 
    //     );
    //     setPersonTypes(response.data);
    // };

    // // Handle form change
    // const loadUserListData = async () => {
    //     const response = await axios.get(
    //         BASE_URL + "/WebApplication/Controllers/getAllUserInList",
    //         { withCredentials: true, } // 🚨 This ensures browser stores cookie 
    //     );
    //     setProjectManagerTypes(response.data);
    // };


    // // Handle form change
    // const loadGroupListData = async () => {
    //     const response = await axios.get(
    //         BASE_URL + "/WebApplication/Controllers/getAllGroupInList",
    //         { withCredentials: true, } // 🚨 This ensures browser stores cookie 
    //     );
    //     setGroupTypes(response.data);
    // };


    const handleUploadAndSubmit = async (e) => {
        e.preventDefault();
        try {

            if (!selectedImage) {
                // alert("Please select an image first!");
                await handleSubmitForm(e);
                return;
            } else {

                const imageData = new FormData();
                imageData.append("image", selectedImage);

                const response = await axios.post(
                    BASE_URL + "/WebApplication/Controllers/uploadImage",
                    imageData,
                    { headers: { "Content-Type": "multipart/form-data" } }
                );
                alert("Image uploaded successfully!");

                // ✅ Directly pass the uploaded image name/path
                await handleSubmitForm(e, response.data);
                return;
            }

        } catch (error) {
            console.error("Error uploading:", error);
        }
    };


    const isBlankOrSpaces = (value = "") =>
        value.trim().length === 0;

    const handleSubmitForm = async (e, uploadedImage) => {
        e.preventDefault();

        if (isBlankOrSpaces(plantName) || isBlankOrSpaces(plantCode)
            || isBlankOrSpaces(plantAddress)) {
            alert("Please fill required column");
            return;
        }

        const data = {
            plantId: parseInt(plantCode),
            plantName,
            plantCode,
            plantDescription,
            plantAddress,
            image: uploadedImage ? "/WebApplication/trainingResouces/" + uploadedImage + ".png" : image,   // ✅ use uploaded image instead of state
            dateTime: "",
            createdBy: "111",
        };

        try {
            const url = object
                ? BASE_URL + "/WebApplication/Controllers/editPlantMaster"
                : BASE_URL + "/WebApplication/Controllers/insertPlantMaster";

            const response = await axios.post(url, data, { withCredentials: true });

            setAlert({ type: "success", message: "Success : " + response.data });
            resetForm();
        } catch (err) {
            setAlert({ type: "danger", message: "Error : " + err.response?.data });
            console.error(err);
        }
    };

    return (
        <div className="card shadow-lg rounded-0 border-0 bg-light d-flex flex-column p-2"
            style={{
                width: "100%",
                minHeight: "100vh",
                background: "#f4f6f8",
            }}>
            {/* Header */}
            <div className="px-4 py-2 position-relative"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>
                {/* Title */}
                <h4 className="text-end fw-bold mb-0"><ClipboardList size={30} viewBox="0 1 24 24" className="me-2 text-white" />
                    {object ? "Update Location" : "New Location"}</h4>
                <div
                    className="position-absolute top-50 start-0 translate-middle-y ms-3"
                    style={{ zIndex: 10 }}
                >
                    <Link
                        to="/WebApplication/dashboard/locationMaster"
                        className="btn btn-light btn-sm d-flex align-items-center fw-semibold shadow-sm"
                    >
                        <ArrowLeft className="me-1" /><span className="d-none d-lg-inline">Back</span>
                    </Link>
                </div>
            </div>


            {error && <p className="text-danger text-center fw-semibold mt-2">{error}</p>}

            {loading ? (
                <LoadingSpinner message={`Loading .....`} />
            ) : (

                <div className="row g-1 p-1" style={{ maxHeight: "90vh", overflowY: "scroll" }}>

                    {/* Right Side - Illustration */}
                    <div className="col-md-4 bg-light rounded-3 shadow-sm">
                        <div className="d-flex justify-content-center align-items-center h-100">
                            <img
                                src={previewUrl || myLogo}  // 👈 replace with uploaded file if exists
                                alt="Project Illustration"
                                className="img-fluid"
                                style={{ maxWidth: "80%", opacity: 0.95 }}
                            />
                        </div>
                    </div>

                    {/* Left Side - Form */}
                    <div className="col-md-8" >
                        <form onSubmit={handleUploadAndSubmit} className="p-2 bg-light rounded-3 shadow-sm" style={{ height: "87vh", overflow: "auto" }}>
                            <div className="row g-1">
                                {/* Plant Name. */}
                                <div className="col-md-6 px-2">
                                    <SearchInputFields
                                        label="Location Name"
                                        type="text"
                                        placeholder=""
                                        value={plantName}
                                        onChange={(e) => setPlantName(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Image */}
                                <div className="col-md-6 px-2">
                                    <InputField
                                        label="Image"
                                        type="file"
                                        accept="image/png, image/jpeg"
                                        // value={customerAddress}
                                        onChange={handleImageChange}
                                    />
                                </div>


                                {/* Project Name */}
                                <div className="col-md-4 px-2">
                                    <SearchInputFields
                                        label="Description"
                                        type="text"
                                        placeholder=""
                                        value={plantCode}
                                        onChange={(e) => setPlantCode(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Project Name */}
                                <div className="col-md-4 px-2">
                                    <SearchInputFields
                                        label="Location Code"
                                        type="text"
                                        placeholder=""
                                        value={plantDescription}
                                        onChange={(e) => setPlantDescription(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Project Manager */}
                                <div className="col-md-4 px-2">
                                    <SearchInputFields
                                        label="Label file Path"
                                        type="text"
                                        placeholder=""
                                        value={plantAddress}
                                        onChange={(e) => setPlantAddress(e.target.value)}
                                        required={true}
                                    />
                                </div>
                                <div className="col-md-4 px-2">
                                    <SearchInputFields
                                        label="Minimum Racks"
                                        type="text"
                                        placeholder=""
                                        value={plantCity}
                                        onChange={(e) => setPlantCity(e.target.value)}
                                        required={true}
                                    />
                                </div>
                                <div className="col-md-8 px-2">
                                    <SearchInputFields
                                        label="Reprint"
                                        type="text"
                                        placeholder=""
                                        value={plantState}
                                        onChange={(e) => setPlantState(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Save Button */}
                                <div className="col-md-4 p-2">
                                    <button
                                        type="submit"
                                        size="lr"
                                        className="btn-woco btn btn-light btn-sm 
                                                    d-flex align-items-center 
                                                    fw-semibold shadow-sm"

                                        // className="btn btn-primary w-100 fw-bold mt-3 rounded-pill shadow-sm"
                                        style={{ fontSize: "1.1rem", letterSpacing: "0.5px" }}
                                    >
                                        {object ? "💾 Update" : "💾 Save"}
                                    </button>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );


};

export default NewLocationForm;
