import axios from "axios";

const BASE_URL = process.env.REACT_APP_BASE_URL;

const axiosInstance = axios.create({
  baseURL: BASE_URL,
  withCredentials: true, // cookie-based auth
});

/* ===============================
   STEP 2: RESPONSE INTERCEPTOR
   =============================== */
axiosInstance.interceptors.response.use(
  (response) => {
    // Success response → just return it
    return response;
  },
  (error) => {
    // If server responded with error
    if (error.response) {
      const { status, data } = error.response;

      // ✅ Redirect ONLY when session expired
      if (
        status === 401 &&
        data?.error === "UNAUTHORIZED" &&
        data?.message === "Session expired. Please login again."
      ) {
        // Clear stored data (optional)
        localStorage.clear();
        sessionStorage.clear();

        // Prevent infinite loop
        if (window.location.pathname !== "/WebApplication/loginpage") {
          window.location.href = "/WebApplication/loginpage";
        }
      }
    }

    // Important: reject error so calling code can handle it
    return Promise.reject(error);
  }
);

export default axiosInstance;
